def get_h3_neighbors(h3_index, ring_k=1):
    # In Uber H3, k_ring(idx, 1) returns the cell + 6 equidistant neighbors
    return h3_lib.grid_disk(h3_index, ring_k)

def hmm_emission_prob(dist_meters, sigma_z=10.0):
    return math.exp(-0.5 * (dist_meters / sigma_z) ** 2) / (math.sqrt(2 * math.pi) * sigma_z)

def hmm_transition_prob(gps_dist, route_dist, beta=5.0):
    return (1.0 / beta) * math.exp(-abs(gps_dist - route_dist) / beta)

def harmonic_mean_speed(speeds_kmh):
    valid = [max(s, 2.0) for s in speeds_kmh if s >= 2.0]
    if not valid:
        return None  # Ignore parked vehicles
    return round(len(valid) / sum(1.0 / s for s in valid), 2)
